        println!("{} scored {}", name, score);
    }

    // Using a closure with a function
    let numbers = vec![1, 2, 3, 4, 5];
    let squares: Vec<_> = numbers.iter().map(|x| x * x).collect();
    println!("Squares: {:?}", squares);

    // Using a struct with field init shorthand
    struct Person {
        name: String,
        age: u8,
    }

    let person = Person {
        name: String::from("Alice"),
        age: 30,
    };

    // Using a method on a struct
    person.print_info();

    // Using a trait and a generic function
    let result = add(3, 5);
    println!("3 + 5 = {result}");
}

// Method on a struct
impl Person {
    fn print_info(&self) {
        println!("Name: {}, Age: {}", self.name, self.age);
    }
}

// Generic function with type inference
fn add<T: std::ops::Add<Output = T>>(a: T, b: T) -> T {
