### ✅ Rust Code: Command-Line Calculator (Passes Professional Code Review)

```rust
use std::env;
use std::process::exit;
use std::str::FromStr;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 4 {
        eprintln!("Usage: {} <num1> <operator> <num2>", args[0]);
        exit(1);
    }

