    let num1 = match num1_str.parse::<f64>() {
        Ok(n) => n,
        Err(_) => {
            eprintln!("Error: '{}' is not a valid number.", num1_str);
            exit(1);
        }
    };

    let num2 = match num2_str.parse::<f64>() {
        Ok(n) => n,
        Err(_) => {
            eprintln!("Error: '{}' is not a valid number.", num2_str);
            exit(1);
        }
    };

    let result = match operator.as_str() {
        "+" => num1 + num2,
        "-" => num1 - num2,
        "*" => num1 * num2,
        "/" => {
            if num2 == 0.0 {
                eprintln!("Error: Division by zero is not allowed.");
                exit(1);
            }
            num1 / num2
        }
        _ => {
            eprintln!("Error: Unsupported operator '{}'. Supported operators: +, -, *, /", operator);
            exit(1);
        }
    };

    println!("Result: {}", result);
}
```

